script:
(function () {
  'use strict';
  // Mortgage payment with taxes, insurance, PMI, HOA and extra payments.
  //   Principal & interest: M = L * i / (1 - (1 + i)^-n), i = annual rate / 12, n = years * 12
  //   (M = L / n at 0%). Each month: interest = balance * i; principal = M - interest (+ extras).
  //   PMI = annual PMI rate * original loan / 12, charged only when the loan is more than 80% of the
  //   home price, until the balance falls to 78% of the price or the term reaches its midpoint.
  // Verified in Node (scratchpad tests): $200,000 at 6% for 30 yrs = $1,199.10/mo, total interest
  //   $231,676.38; $320,000 at 7.373% for 30 yrs = $2,209.72/mo (cross-checked with a published
  //   calculator's default); $300,000 at 0% for 30 yrs = $833.33/mo; final balance is exactly 0;
  //   PMI months match an independent loop (109 payments for $360,000 at 6.5% on a $400,000 home);
  //   payoff month with a fixed extra matches n = -ln(1 - L*i/(M+X)) / ln(1+i); extra payments
  //   never overpay; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function amortize(o) {
    var pay = monthlyPayment(o.loan, o.rate, o.months);
    var i = o.rate / 12, bal = o.loan, rows = [];
    var totalInterest = 0, totalPmi = 0, pmiMonths = 0;
    var pmiMonthly = o.pmiRate * o.loan / 12;
    var pmiOn = pmiMonthly > 0 && o.loan > 0.8 * o.homeValue;
    for (var m = 1; m <= o.months && bal > 0.005; m++) {
      var interest = bal * i;
      var pmi = (pmiOn && bal > 0.78 * o.homeValue && m <= o.months / 2) ? pmiMonthly : 0;
      var principal = Math.min(pay - interest, bal);
      var extra = o.extraMonthly + (m % 12 === 0 ? o.extraYearly : 0) + (m === o.onceAt ? o.once : 0);
      extra = Math.max(0, Math.min(extra, bal - principal));
      bal -= principal + extra;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalPmi += pmi;
      if (pmi > 0) pmiMonths++;
      rows.push({ n: m, interest: interest, principal: principal + extra, pmi: pmi, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest, totalPmi: totalPmi, pmiMonths: pmiMonths };
  }

  function monthLabel(start, offset) {
    var t = start + offset;
    return MONTHS[t % 12] + ' ' + Math.floor(t / 12);
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['mcMonthlyTotal', 'mcLoanAmount', 'mcTotalInterest', 'mcPayoffDate', 'mcPI', 'mcTaxMonthly',
     'mcInsMonthly', 'mcPmiMonthly', 'mcHoaMonthly', 'mcDownAmount', 'mcPaymentCount', 'mcTotalPI',
     'mcTotalPmi'].forEach(function (id) { setText(id, '–'); });
    setText('mcPmiNote', '');
    setText('mcDownHint', '');
    el('mcSavings').hidden = true;
    el('mcSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var head = el('mcScheduleHead'), body = el('mcSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var rows = last.rows, start = last.start, html = [];
    if (el('mcView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Month</th><th scope="col">Payment</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Balance</th></tr>';
      rows.forEach(function (row) {
        html.push('<tr><td>' + monthLabel(start, row.n - 1) + '</td><td>' + money.format(row.principal + row.interest) +
          '</td><td>' + money.format(row.principal) + '</td><td>' + money.format(row.interest) + '</td><td>' +
          money.format(row.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Ending balance</th></tr>';
      var year = null, p = 0, intr = 0, bal = 0;
      rows.forEach(function (row, idx) {
        var y = Math.floor((start + row.n - 1) / 12);
        if (year !== null && y !== year) {
          html.push('<tr><td>' + year + '</td><td>' + money.format(p) + '</td><td>' + money.format(intr) + '</td><td>' + money.format(bal) + '</td></tr>');
          p = 0; intr = 0;
        }
        year = y; p += row.principal; intr += row.interest; bal = row.balance;
        if (idx === rows.length - 1) {
          html.push('<tr><td>' + year + '</td><td>' + money.format(p) + '</td><td>' + money.format(intr) + '</td><td>' + money.format(bal) + '</td></tr>');
        }
      });
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var price = read('mcPrice'), down = read('mcDown'), downUnit = el('mcDownUnit').value,
        years = read('mcTerm'), rate = read('mcRate'),
        startMonth = parseInt(el('mcStartMonth').value, 10), startYear = read('mcStartYear'),
        tax = read('mcTax', true), taxUnit = el('mcTaxUnit').value, ins = read('mcInsurance', true),
        pmiRate = read('mcPmi', true), hoa = read('mcHoa', true),
        exMonthly = read('mcExtraMonthly', true), exYearly = read('mcExtraYearly', true),
        exOnce = read('mcExtraOnce', true), exOnceAt = read('mcExtraOnceAt', true);
    var downAmt = downUnit === 'percent' ? price * down / 100 : down;
    var error = el('mcError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a home price greater than $0.';
    else if (isNaN(down) || down < 0 || !(downAmt < price)) msg = 'Enter a down payment of 0 or more that is less than the home price.';
    else if (isNaN(years) || years < 1 || years > 50 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 50 whole years.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(startMonth) || isNaN(startYear) || startYear < 1900 || startYear > 2200 || startYear % 1 !== 0) msg = 'Enter a valid first payment month and year.';
    else if ([tax, ins, pmiRate, hoa, exMonthly, exYearly, exOnce].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Taxes, insurance, PMI, HOA and extra payments cannot be negative.';
    else if (taxUnit === 'percent' && tax > 20) msg = 'Enter a property tax rate of 20% or less.';
    else if (pmiRate > 5) msg = 'Enter a PMI rate of 5% or less.';
    else if (exOnce > 0 && (isNaN(exOnceAt) || exOnceAt < 1 || exOnceAt % 1 !== 0)) msg = 'Enter the payment number (1 or higher) for the one-time extra payment.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var loan = price - downAmt, months = years * 12;
    var annualTax = taxUnit === 'percent' ? price * tax / 100 : tax;
    var opts = { loan: loan, rate: rate / 100, months: months, homeValue: price, pmiRate: pmiRate / 100,
                 extraMonthly: 0, extraYearly: 0, once: 0, onceAt: 0 };
    var base = amortize(opts);
    opts.extraMonthly = exMonthly; opts.extraYearly = exYearly; opts.once = exOnce; opts.onceAt = exOnceAt;
    var r = amortize(opts);
    var start = startYear * 12 + startMonth;
    var firstPmi = r.rows.length ? r.rows[0].pmi : 0;

    setText('mcDownHint', downUnit === 'percent' ? '= ' + money.format(downAmt) : '= ' + (downAmt / price * 100).toFixed(1) + '% of the price');
    setText('mcMonthlyTotal', money.format(r.payment + annualTax / 12 + ins / 12 + firstPmi + hoa));
    setText('mcLoanAmount', money.format(loan));
    setText('mcTotalInterest', money.format(r.totalInterest));
    setText('mcPayoffDate', monthLabel(start, r.rows.length - 1));
    setText('mcPI', money.format(r.payment));
    setText('mcTaxMonthly', money.format(annualTax / 12));
    setText('mcInsMonthly', money.format(ins / 12));
    setText('mcPmiMonthly', money.format(firstPmi));
    setText('mcHoaMonthly', money.format(hoa));
    setText('mcDownAmount', money.format(downAmt));
    setText('mcPaymentCount', String(r.rows.length));
    setText('mcTotalPI', money.format(loan + r.totalInterest));
    setText('mcTotalPmi', money.format(r.totalPmi));

    var note;
    if (loan <= 0.8 * price) note = 'No PMI: the loan is 80% or less of the home price.';
    else if (pmiRate === 0) note = 'PMI not included. Enter your lender’s PMI rate to add it.';
    else note = 'PMI charged for ' + r.pmiMonths + ' payments, through ' + monthLabel(start, r.pmiMonths - 1) + '.';
    setText('mcPmiNote', note);

    var hasExtra = exMonthly > 0 || exYearly > 0 || (exOnce > 0 && exOnceAt <= months);
    el('mcSavings').hidden = !hasExtra;
    setText('mcInterestSaved', money.format(Math.max(0, base.totalInterest - r.totalInterest)));
    setText('mcTimeSaved', duration(Math.max(0, base.rows.length - r.rows.length)));

    last = { rows: r.rows, start: start };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mcForm');
    if (!form) return;
    var now = new Date(), next = now.getFullYear() * 12 + now.getMonth() + 1;
    el('mcStartMonth').value = String(next % 12);
    el('mcStartYear').value = String(Math.floor(next / 12));
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('mcView').addEventListener('change', renderSchedule);
    update();
  });
})();
